import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { getCar } from '../services/carService';
import { useAuth } from '../context/AuthContext';
import { motion, AnimatePresence } from 'framer-motion';
import api, { getImageUrl } from '../services/api';
import LoanModal from '../components/LoanModal';
import TestDriveModal from '../components/TestDriveModal';
import styles from './CarDetailPage.module.css';

const CarDetailPage = () => {
  const { id } = useParams();
  const { user } = useAuth();
  const [car, setCar] = useState(null);
  const [showLoan, setShowLoan] = useState(false);
  const [showTestDrive, setShowTestDrive] = useState(false);
  const [showPurchaseModal, setShowPurchaseModal] = useState(false); // Фактически открывает блок покупки на странице
  const [purchaseSuccess, setPurchaseSuccess] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState('card');
  const [activeImage, setActiveImage] = useState(null);

  // Состояния для кредита при покупке
  const [creditParams, setCreditParams] = useState({
    amount: '',
    term: 36,
    rate: 12,
    downPayment: '',
  });
  const [creditCalculated, setCreditCalculated] = useState(null);
  const [creditForm, setCreditForm] = useState({
    fullName: user?.full_name || '',
    phone: user?.phone || '',
  });

  useEffect(() => {
    getCar(id).then(res => {
      setCar(res.data);
      const imgs = res.data.images || [];
      if (imgs.length > 0) setActiveImage(imgs[0].image_url);
      else setActiveImage(res.data.image_url || '/images/default-car.jpg');
    }).catch(console.error);
  }, [id]);

  useEffect(() => {
    if (paymentMethod === 'credit') {
      calculateCredit();
    }
  }, [creditParams.amount, creditParams.term, creditParams.rate, creditParams.downPayment, paymentMethod]);

  const calculateCredit = () => {
    const price = car?.price || 0;
    const down = parseFloat(creditParams.downPayment) || 0;
    const principal = parseFloat(creditParams.amount) || (price - down);
    const months = parseInt(creditParams.term);
    const annualRate = parseFloat(creditParams.rate);

    if (isNaN(principal) || isNaN(months) || isNaN(annualRate) || principal <= 0) {
      setCreditCalculated(null);
      return;
    }

    const monthlyRate = annualRate / 12 / 100;
    let monthlyPayment;
    if (monthlyRate === 0) {
      monthlyPayment = principal / months;
    } else {
      monthlyPayment = principal * (monthlyRate * Math.pow(1 + monthlyRate, months)) / (Math.pow(1 + monthlyRate, months) - 1);
    }
    const totalPayment = monthlyPayment * months;
    const overpayment = totalPayment - principal;

    setCreditCalculated({
      monthly_payment: Math.round(monthlyPayment),
      total_payment: Math.round(totalPayment),
      overpayment: Math.round(overpayment),
    });
  };

  const handlePurchase = async () => {
    if (!user) {
      alert('Войдите, чтобы совершить покупку');
      return;
    }
    try {
      const res = await api.post('/purchases/', { car_id: car.id });
      const receipt = {
        id: res.data.purchase?.id || Date.now(),
        brand: car.brand,
        model: car.model,
        year: car.year,
        price: car.price,
        purchase_date: new Date().toISOString(),
        paymentMethod,
        credit: paymentMethod === 'credit' ? {
          ...creditParams,
          ...creditCalculated,
          ...creditForm,
        } : null,
      };
      const savedReceipts = JSON.parse(localStorage.getItem('purchaseReceipts') || '[]');
      savedReceipts.push(receipt);
      localStorage.setItem('purchaseReceipts', JSON.stringify(savedReceipts));
      setPurchaseSuccess(true);
      setShowPurchaseModal(false); // Закрываем саму панель выбора после успеха
    } catch (err) {
      alert('Ошибка оформления покупки');
    }
  };

  if (!car) return <div className={styles.loading}>Загрузка...</div>;

  const allImages = car.images?.length ? car.images.map(img => img.image_url) : [car.image_url || '/images/default-car.jpg'];

  return (
    <motion.div className={styles.container} initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}>
      <div className={styles.content}>
        
        {/* ЛЕВАЯ КОЛОНКА: ГАЛЕРЕЯ */}
        <div className={styles.galleryWrapper}>
          <motion.div className={styles.mainImage} whileHover={{ scale: 1.01 }}>
            <img src={getImageUrl(activeImage || allImages[0])} alt={car.model} className={styles.image} />
          </motion.div>
          {allImages.length > 1 && (
            <div className={styles.thumbnails}>
              {allImages.map((url, idx) => (
                <img key={idx} src={getImageUrl(url)} alt={`view ${idx + 1}`} className={`${styles.thumb} ${url === activeImage ? styles.activeThumb : ''}`} onClick={() => setActiveImage(url)} />
              ))}
            </div>
          )}
        </div>

        {/* ПРАВАЯ КОЛОНКА: ИНФОРМАЦИЯ И ОФОРМЛЕНИЕ */}
        <div className={styles.info}>
          <h1 className={styles.title}>{car.brand} {car.model}</h1>
          <p className={styles.year}>{car.year} год</p>
          <p className={styles.price}>{car.price.toLocaleString('ru-RU')} ₽</p>
          {car.description && <p className={styles.description}>{car.description}</p>}

          {/* Главные кнопки действий отображаются только если покупка еще не оформлена */}
          {!purchaseSuccess && !showPurchaseModal && (
            <>
              <motion.button className={styles.buyButton} whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.99 }} onClick={() => setShowPurchaseModal(true)}>
                Купить автомобиль
              </motion.button>

              <div className={styles.actions}>
                <button className={styles.secondaryButton} onClick={() => setShowLoan(true)}>Рассчитать кредит</button>
                <button className={styles.secondaryButton} onClick={() => setShowTestDrive(true)}>Записаться на тест-драйв</button>
              </div>
            </>
          )}

          {/* КРАСИВЫЙ ИНЛАЙН-БЛОК ПОКУПКИ */}
          <AnimatePresence>
            {showPurchaseModal && !purchaseSuccess && (
              <motion.div className={styles.inlinePurchasePanel} initial={{ opacity: 0, height: 0 }} animate={{ opacity: 1, height: 'auto' }} exit={{ opacity: 0, height: 0 }}>
                <div className={styles.panelHeader}>
                  <h3 className={styles.panelTitle}>Выбор параметров оплаты</h3>
                  <button className={styles.closePanelBtn} onClick={() => setShowPurchaseModal(false)}>✕</button>
                </div>
                
                <div className={styles.paymentMethodsGrid}>
                  <label className={`${styles.paymentTile} ${paymentMethod === 'card' ? styles.activeTile : ''}`}>
                    <input type="radio" name="payment" value="card" checked={paymentMethod === 'card'} onChange={() => setPaymentMethod('card')} />
                    <span className={styles.tileIcon}>💳</span>
                    <span className={styles.tileText}>Карта</span>
                  </label>
                  <label className={`${styles.paymentTile} ${paymentMethod === 'cash' ? styles.activeTile : ''}`}>
                    <input type="radio" name="payment" value="cash" checked={paymentMethod === 'cash'} onChange={() => setPaymentMethod('cash')} />
                    <span className={styles.tileIcon}>💵</span>
                    <span className={styles.tileText}>Наличные</span>
                  </label>
                  <label className={`${styles.paymentTile} ${paymentMethod === 'credit' ? styles.activeTile : ''}`}>
                    <input type="radio" name="payment" value="credit" checked={paymentMethod === 'credit'} onChange={() => setPaymentMethod('credit')} />
                    <span className={styles.tileIcon}>🏛️</span>
                    <span className={styles.tileText}>Кредит</span>
                  </label>
                </div>

                {/* Параметры кредита */}
                {paymentMethod === 'credit' && (
                  <motion.div className={styles.creditFormBlock} initial={{ opacity: 0, y: -10 }} animate={{ opacity: 1, y: 0 }}>
                    <h4 className={styles.creditFormTitle}>Анкета заёмщика</h4>
                    
                    <div className={styles.inputGroupRow}>
                      <div className={styles.inputField}>
                        <label>Первый взнос (₽)</label>
                        <input type="number" value={creditParams.downPayment} onChange={(e) => setCreditParams(prev => ({ ...prev, downPayment: e.target.value }))} placeholder="0" />
                      </div>
                      <div className={styles.inputField}>
                        <label>Срок (мес.)</label>
                        <input type="number" value={creditParams.term} onChange={(e) => setCreditParams(prev => ({ ...prev, term: e.target.value }))} />
                      </div>
                    </div>

                    <div className={styles.inputField}>
                      <label>ФИО заявителя</label>
                      <input type="text" value={creditForm.fullName} onChange={(e) => setCreditForm(prev => ({ ...prev, fullName: e.target.value }))} placeholder="Иванов Иван Иванович" />
                    </div>
                    
                    <div className={styles.inputField}>
                      <label>Контактный телефон</label>
                      <input type="tel" value={creditForm.phone} onChange={(e) => setCreditForm(prev => ({ ...prev, phone: e.target.value }))} placeholder="+7 (999) 123-45-67" />
                    </div>

                    {creditCalculated && (
                      <div className={styles.creditSummaryBadge}>
                        <span>Ежемесячный платёж:</span>
                        <strong>{creditCalculated.monthly_payment.toLocaleString()} ₽/мес.</strong>
                      </div>
                    )}
                  </motion.div>
                )}

                <div className={styles.panelActions}>
                  <button className={styles.panelConfirmBtn} onClick={handlePurchase}>
                    {paymentMethod === 'credit' ? 'Отправить заявку банк' : 'Подтвердить покупку'}
                  </button>
                  <button className={styles.panelCancelBtn} onClick={() => setShowPurchaseModal(false)}>Отмена</button>
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          {/* ПРЕМИАЛЬНЫЙ СТАТУС УСПЕХА ВМЕСТО ФОРМЫ */}
          <AnimatePresence>
            {purchaseSuccess && (
              <motion.div className={styles.premiumSuccessCard} initial={{ scale: 0.95, opacity: 0 }} animate={{ scale: 1, opacity: 1 }}>
                <div className={styles.successBadgeIcon}>
                  <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3">
                    <polyline points="20 6 9 17 4 12"></polyline>
                  </svg>
                </div>
                <h3 className={styles.successCardTitle}>
                  {paymentMethod === 'credit' ? 'Заявка принята' : 'Автомобиль куплен!'}
                </h3>
                <p className={styles.successCardDesc}>
                  {paymentMethod === 'credit' 
                    ? 'Мы отправили запрос в банк-партнер. Менеджер свяжется с вами сразу после получения одобрения.' 
                    : 'Поздравляем с приобретением! Полный финансовый чек и детали сделки уже сгенерированы в вашем профиле.'}
                </p>
                <div className={styles.successCardFooter}>
                  <span>Luxury Dealer Premium Service</span>
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          {/* ХАРАКТЕРИСТИКИ */}
          {(car.engine_volume || car.power || car.fuel_type || car.consumption || car.drive_type || car.transmission || car.acceleration || car.max_speed || car.clearance || car.seats) && (
            <div className={styles.specs}>
              <h3>Характеристики</h3>
              <div className={styles.specsGrid}>
                {car.engine_volume && <div className={styles.specItem}><span>Объём</span><strong>{car.engine_volume} л</strong></div>}
                {car.power && <div className={styles.specItem}><span>Мощность</span><strong>{car.power} л.с.</strong></div>}
                {car.fuel_type && <div className={styles.specItem}><span>Топливо</span><strong>{{petrol:'Бензин', diesel:'Дизель', hybrid:'Гибрид', electric:'Электро'}[car.fuel_type] || car.fuel_type}</strong></div>}
                {car.consumption && <div className={styles.specItem}><span>Расход</span><strong>{car.consumption} л</strong></div>}
                {car.drive_type && <div className={styles.specItem}><span>Привод</span><strong>{car.drive_type}</strong></div>}
                {car.transmission && <div className={styles.specItem}><span>КПП</span><strong>{{manual:'Мех.', automatic:'Авт.', robot:'Роб.', variator:'Вар.'}[car.transmission] || car.transmission}</strong></div>}
              </div>
            </div>
          )}

        </div>
      </div>

      {showLoan && <LoanModal car={car} onClose={() => setShowLoan(false)} />}
      {showTestDrive && <TestDriveModal carId={car.id} onClose={() => setShowTestDrive(false)} />}
    </motion.div>
  );
};

export default CarDetailPage;
